const items = $input.all();
const now = Date.now();
const TWO_DAYS = 2 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const ts = item.json['timestamp'];
  const status = item.json['Status'];
  if (!ts) return false;
  if (status !== 'Welcome Email Sent') return false;
  return (now - new Date(ts).getTime()) >= TWO_DAYS;
});

return due;

const aiResps = $input.all();
const clients = $('🔍 Filter: 2+ Days Since Welcome').all();

return aiResps.map((aiResp, i) => {
  const client = clients[i]?.json || {};
  let email = {};
  try {
    const raw = aiResp.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    email = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch (e) {
    email = {
      subject: `Quick follow-up \u2014 Scheduling our kickoff call for ${client.serviceRequired}`,
      body: `Hi ${client.clientName},\n\nHope you're doing well! Just following up on my welcome email from a couple of days ago. We're excited to get started on the ${client.serviceRequired} project for ${client.clientCompany}.\n\nWould any of these times work for a 30-minute kickoff call?\n- Tomorrow at 11 AM IST\n- Tomorrow at 3 PM IST\n- Day after at 10 AM IST\n\nLooking forward to kicking things off!\n\nBest regards,\n${client.yourName}`
    };
  }

  // FIX: mailto link should point to yourEmail (agency) not clientEmail
  // The client clicks the button to reply TO THE AGENCY, not to themselves
  const replyToEmail = client.yourEmail || 'kspandian32@gmail.com';

  const htmlBody = `<!DOCTYPE html><html><head><style>body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;line-height:1.6;color:#1a202c;margin:0;padding:0;background-color:#f7fafc}.container{max-width:600px;margin:20px auto;border-radius:16px;overflow:hidden;background-color:#fff;box-shadow:0 10px 25px rgba(0,0,0,.1)}.header{background:linear-gradient(135deg,#4f46e5,#7c3aed);color:#fff;padding:40px 20px;text-align:center}.content{padding:40px}.footer{background-color:#f8fafc;padding:20px;text-align:center;font-size:13px;color:#718096;border-top:1px solid #edf2f7}.button{display:inline-block;padding:14px 30px;background:linear-gradient(135deg,#4f46e5,#7c3aed);color:#fff!important;text-decoration:none;border-radius:12px;font-weight:700;margin-top:25px}.highlight{color:#4f46e5;font-weight:700}</style></head><body><div class="container"><div class="header"><h1 style="margin:0;font-size:28px">Kickoff Call Scheduling</h1><p style="margin:8px 0 0;font-size:16px;opacity:.9">Project: ${client.serviceRequired}</p></div><div class="content"><p style="font-size:18px">Hi <span class="highlight">${client.clientName}</span>,</p><p style="font-size:16px;color:#4a5568">${(email.body || '').replace(/\n/g, '<br>')}</p><div style="text-align:center;margin-top:30px"><p style="font-size:14px;color:#718096">Ready to start?</p><a href="mailto:${replyToEmail}?subject=Re: ${encodeURIComponent(email.subject || client.serviceRequired + ' Kickoff')}&body=${encodeURIComponent('Hi ' + (client.yourName || 'Team') + ',\n\nI would like to confirm the following time slot:\n\n')}" class="button">Confirm Meeting Time</a></div></div><div class="footer"><p>Sent by <strong>${client.agencyName}</strong></p><p style="margin-top:0">Empowering ${client.clientCompany} with AI</p></div></div></body></html>`;

  return { json: { ...client, followUpSubject: email.subject, followUpBody: htmlBody } };
});

// Global Config (cogdef) - Pulling from Environment Variables
const config = {
  safeMode: $env.SAFE_MODE === 'true',
  logDrainId: $env.LOG_DRAIN_ID || "FEK7PNwR6I3XZygD",
  spreadsheetId: $env.SPREADSHEET_ID || "16dAe64XCQ_iecfAlrrdG5n6TtJyr2cDrMmIN4Uv9xBU",
  env: $env.NODE_ENV || "production",
  roiMins: 30
};

return $input.all().map(item => ({
  json: { 
    ...item.json,
    ...config,
    cogdef: config 
  }
}));
